export function findById(id) { return DOCTORS.find(x => x.id === id); }
export function search(q) {
  const s = String(q||'').toLowerCase();
  if (!s) return DOCTORS.slice();
  return DOCTORS.filter(x => JSON.stringify(x).toLowerCase().includes(s));
}
export function bySpecialty(spec) {
  return DOCTORS.filter(x => (x.specialty||x.category||'').toLowerCase() === String(spec||'').toLowerCase());
}
export function enabledOnly() { return DOCTORS.filter(x => x.enabled !== false); }
export const COUNT = DOCTORS.length;
